p = "src/components/NodeSearchModal.tsx"
s = open(p).read()

old_render = '''  useEffect(() => {
    const container = containerRef.current;
    if (!container || !file || loaded?.file !== file) return;

    container.empty();
    const component = new Component();
    void MarkdownRenderer.render(
      app,
      loaded.text.trim() || "This note is empty.",
      container,
      file.path,
      component,
    );

    return () => {
      component.unload();
      container.empty();
    };
  }, [app, file, loaded]);
'''
new_render = '''  useEffect(() => {
    const container = containerRef.current;
    if (!container || !file || loaded?.file !== file) return;

    container.empty();
    setRenderedFile(null);
    const component = new Component();
    let cancelled = false;
    void MarkdownRenderer.render(
      app,
      loaded.text.trim() || "This note is empty.",
      container,
      file.path,
      component,
    )
      .then(() => waitForImages(container))
      .then(() => {
        if (!cancelled) setRenderedFile(file);
      });

    return () => {
      cancelled = true;
      component.unload();
      container.empty();
    };
  }, [app, file, loaded]);

  // Separate from rendering, so moving between two lines of one note only re-scrolls.
  const taggedLine = result?.tagLine?.line;
  useEffect(() => {
    const container = containerRef.current;
    if (!container || !loaded || renderedFile !== loaded.file) return;
    if (taggedLine === undefined) {
      container.scrollTop = 0;
      return;
    }

    const target = findTaggedLineElement({
      container,
      cache: app.metadataCache.getFileCache(loaded.file),
      line: taggedLine,
      sourceLine: loaded.text.split("\\n")[taggedLine] ?? "",
    });
    if (!target) return;
    target.scrollIntoView({ block: "center" });
    target.addClass(PREVIEW_FLASH_CLASS);
    const clearFlash = () => target.removeClass(PREVIEW_FLASH_CLASS);
    target.addEventListener("animationend", clearFlash, { once: true });
    return () => {
      target.removeEventListener("animationend", clearFlash);
      clearFlash();
    };
  }, [app, loaded, renderedFile, taggedLine]);
'''
assert old_render in s
s = s.replace(old_render, new_render)

old_state = '''  const [loaded, setLoaded] = useState<{ file: TFile; text: string } | null>(
    null,
  );
'''
assert old_state in s
