// Nested lists belong to other items, and footnote refs render as "[n]".
const ownText = (el: Element): string => {
  const clone = el.cloneNode(true) as Element;
  clone.querySelectorAll("ul, ol, sup.footnote-ref").forEach((n) => n.remove());
