  { caption: "List line candidate", file: "$D/3-a2-list-line-candidate.png" },
  { caption: "Heading candidate (auto-active)", file: "$D/4-a3-heading-candidate-auto-active.png" },
].map((f) => ({ caption: f.caption, name: f.file.split("/").pop(), base64: fs.readFileSync(f.file).toString("base64") }));
const session = await openRoamSession({ slot: "1" });
try {
  await session.page.evaluate("globalThis.__name = globalThis.__name || ((f) => f)");
  const done = await session.page.evaluate(async (fixes: any[]) => {
    const api = (window as any).roamAlphaAPI;
    const run = api.q('[:find ?u . :in \$ ?s :where [?b :block/string ?s] [?b :block/uid ?u]]', "2026-09-27 · 12dfa6b7 · obsidian-cdp");
