      const url = ret.trim().match(/\((https?:\/\/\S+?)\)\$/)?.[1] ?? (/^https?:\/\//.test(ret.trim()) ? ret.trim() : null);
      if (!url) { out.push("bad upload: " + f.caption); continue; }
      await api.data.block.update({ block: { uid, string: f.caption + " ![](" + url + ")" } });
      out.push("fixed: " + f.caption);
    }
    return out;
  }, fixes);
  console.log(done.join("\n"));
} finally {
  await session.close();
}
EOF
